import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
export default class FormattedMoney extends Component {
  view() {
    const currencyName = app.forum.attribute('pointSystem.currency_name') || '积分';
    return m('span', `${this.attrs.money} ${currencyName}`);
  }
}
flarum.reg.add('lowseekai-money-rewards', 'forum/components/FormattedMoney', FormattedMoney);